DELETE FROM `dynasty`;
INSERT INTO `dynasty` (
  `dynasty_id`, `name`, `period`, `era`, `period_tag`, `is_unified`,
  `description`, `highlights`, `capital`, `location`, `ethnic_group`,
  `founder`, `map_url`, `map_description`, `sort_order`, `is_active`
) VALUES
('three-sovereigns', '三皇五帝', '约前2852年-约前2070年', 'ancient', 'ancient', 1, '中国上古传说中的帝王时期，包括三皇（燧人氏、伏羲氏、神农氏）和五帝（黄帝、颛顼、帝喾、尧、舜），是中华文明的起源时期。', '["燧人氏钻木取火","伏羲氏创八卦","神农氏尝百草","黄帝统一华夏"]', '无固定都城', '黄河流域', '华夏族', '燧人氏', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '三皇五帝时期的活动范围主要在黄河中下游地区，是中华文明的发祥地。', 0, 1),
('xia', '夏朝', '约前2070年-约前1600年', 'ancient', 'xia-shang-zhou', 1, '中国历史上第一个世袭制朝代，由禹建立。夏朝的建立标志着中国进入了国家社会，结束了原始社会的禅让制。', '["禹建立夏朝","确立世袭制","制定历法","铸造九鼎"]', '大夏（今山西夏县）、斟鄩（今河南偃师）、阳城（今河南洛阳）', '河南、山西一带', '华夏族', '禹', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '夏朝疆域主要分布在黄河中下游地区，是中国历史上第一个有明确历史记载的朝代。', 1, 1),
('han', '寒朝', '约前1993年-约前1933年', 'ancient', 'xia-shang-zhou', 1, '夏朝时期的一个政权，由寒浞建立。寒浞是夏朝东夷族伯明氏的后裔，推翻了夏朝的统治，建立了自己的政权。', '["寒浞建立寒朝","统治黄河中下游地区","后被少康所灭"]', '穷石（今河南洛阳）', '河南一带', '东夷族', '寒浞', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '寒朝疆域主要分布在黄河中下游地区，是夏朝时期的一个重要政权。', 2, 1),
('shang', '商朝', '约前1600年-前1046年', 'ancient', 'xia-shang-zhou', 1, '中国历史上第二个朝代，由商汤建立。商朝是中国青铜器时代的鼎盛时期，甲骨文的使用标志着中国文字的正式形成。', '["商汤灭夏","甲骨文的使用","青铜器的发展","盘庚迁殷"]', '亳（今河南商丘）、嚣、相、邢、庇、奄、殷（今河南安阳）', '河南、河北、山东一带', '华夏族', '商汤', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '商朝疆域较夏朝有所扩大，南至长江流域，北至河北北部。', 3, 1),
('western-zhou', '西周', '前1046年-前771年', 'ancient', 'xia-shang-zhou', 1, '周朝的前半期，由周武王建立。西周确立了分封制和宗法制，是中国古代礼乐文明的鼎盛时期。', '["周武王灭商","周公旦摄政","分封诸侯","制礼作乐"]', '镐京（今陕西西安）', '陕西、河南、山东等地', '华夏族', '周武王姬发', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '西周疆域西起甘肃东部，东至山东半岛，南至长江流域，北至河北北部。', 4, 1),
('eastern-zhou', '东周', '前770年-前256年', 'ancient', 'xia-shang-zhou', 0, '周朝的后半期，周平王东迁洛邑后开始。东周分为春秋和战国两个时期，是中国历史上思想文化繁荣的时期。', '["周平王东迁","春秋五霸","战国七雄","百家争鸣"]', '洛邑（今河南洛阳）', '河南一带', '华夏族', '周平王姬宜臼', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '东周时期周王室衰微，诸侯割据，主要诸侯国包括齐、晋、楚、秦等。', 5, 1),
('spring-autumn', '春秋时期', '前770年-前476年', 'ancient', 'spring-autumn', 0, '东周的前半期，诸侯争霸，百家争鸣，是中国历史上思想文化繁荣的时期。', '["齐桓公称霸","晋文公称霸","百家争鸣","孔子创立儒家"]', '洛邑（名义上）', '中原各地', '华夏族', '周平王', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '春秋时期，周王室衰微，诸侯割据，主要诸侯国包括齐、晋、楚、秦等。', 6, 1),
('warring-states', '战国时期', '前475年-前221年', 'ancient', 'spring-autumn', 0, '东周的后半期，七雄争霸，最终秦国统一六国。', '["三家分晋","商鞅变法","长平之战","合纵连横"]', '七国各有都城', '中原及四方', '华夏族', '韩赵魏三家分晋', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '战国时期，形成了齐、楚、燕、韩、赵、魏、秦七雄并立的局面。', 7, 1),
('lu', '鲁国', '前1043年-前255年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周公旦之子伯禽建立，是春秋时期的重要诸侯国之一。', '["伯禽建立鲁国","孔子的故乡","周礼的保存者"]', '曲阜（今山东曲阜）', '山东一带', '华夏族', '鲁文公伯禽', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '鲁国位于山东曲阜一带，是春秋时期的文化中心。', 8, 1),
('qi', '齐国', '前1046年-前221年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由姜太公姜子牙建立，是春秋五霸之一，战国七雄之一。', '["姜子牙建立齐国","齐桓公称霸","管仲改革"]', '营丘（今山东临淄）', '山东一带', '华夏族', '齐太公姜子牙', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '齐国位于山东临淄一带，是春秋时期的强国之一。', 9, 1),
('song', '宋国', '前11世纪-前286年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由商纣王的庶兄微子启建立，是春秋时期的重要诸侯国之一。', '["微子启建立宋国","宋襄公称霸","商业发达"]', '商丘（今河南商丘）', '河南一带', '华夏族', '宋微子', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '宋国位于河南商丘一带，是春秋时期的重要诸侯国。', 10, 1),
('chen', '陈国', '前1046年-前478年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周武王的女婿妫满建立，是春秋时期的重要诸侯国之一。', '["妫满建立陈国","陈胡公受封","陈完奔齐"]', '宛丘（今河南淮阳）', '河南一带', '华夏族', '陈胡公妫满', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '陈国位于河南淮阳一带，是春秋时期的重要诸侯国。', 11, 1),
('wei', '卫国', '约前1117年-前208年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周武王的弟弟康叔封建立，是春秋时期的重要诸侯国之一。', '["康叔封建立卫国","卫文公复国","卫灵公时期"]', '沫（今河南淇县）', '河南一带', '华夏族', '康叔封', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '卫国位于河南淇县一带，是春秋时期的重要诸侯国。', 12, 1),
('cai', '蔡国', '前1046年-前447年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周武王的弟弟蔡叔度建立，是春秋时期的重要诸侯国之一。', '["蔡叔度建立蔡国","蔡仲复国","蔡昭侯迁都"]', '上蔡（今河南上蔡）', '河南一带', '华夏族', '蔡叔度', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '蔡国位于河南上蔡一带，是春秋时期的重要诸侯国。', 13, 1),
('cao', '曹国', '前1046年-前487年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周武王的弟弟曹叔振铎建立，是春秋时期的重要诸侯国之一。', '["曹叔振铎建立曹国","曹共公时期","被宋国所灭"]', '陶丘（今山东定陶）', '山东一带', '华夏族', '曹叔振铎', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '曹国位于山东定陶一带，是春秋时期的重要诸侯国。', 14, 1),
('jin', '晋国', '前1033年-前376年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由周武王的儿子唐叔虞建立，是春秋时期的强国之一，后来分裂为韩、赵、魏三国。', '["唐叔虞建立晋国","晋文公称霸","三家分晋"]', '绛山（今山西翼城）', '山西一带', '华夏族', '唐叔虞', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '晋国位于山西翼城一带，是春秋时期的强国之一。', 15, 1),
('qin-state', '秦国', '前1044年-前207年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由秦非子建立，是战国七雄之一，后来统一了六国，建立了秦朝。', '["秦非子建立秦国","商鞅变法","统一六国"]', '秦邑（今甘肃天水）', '甘肃一带', '华夏族', '秦非子', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '秦国位于甘肃天水一带，是战国时期的强国之一。', 16, 1),
('chu', '楚国', '前1042年-前223年', 'ancient', 'spring-autumn', 0, '周朝的诸侯国，由熊绎建立，是春秋五霸之一，战国七雄之一。', '["熊绎建立楚国","楚庄王称霸","屈原投江"]', '丹阳（今湖北秭归）', '湖北一带', '华夏族', '熊绎', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '楚国位于湖北秭归一带，是春秋时期的强国之一。', 17, 1),
('qin', '秦朝', '前221年-前206年', 'imperial', 'qin-han', 1, '中国历史上第一个统一的多民族的中央集权国家，由秦始皇嬴政建立。秦朝统一了文字、货币、度量衡，修建了万里长城，确立了中央集权制度。', '["秦始皇统一六国","实行郡县制","统一文字、货币、度量衡","修建万里长城","焚书坑儒"]', '咸阳（今陕西咸阳）', '全国', '华夏族', '秦始皇嬴政', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '秦朝疆域东至东海，西至陇西，南至南海，北至长城一带，是中国历史上第一个统一的大帝国。', 18, 1),
('western-han', '西汉', '前202年-公元9年', 'imperial', 'qin-han', 1, '汉朝的前半期，由刘邦建立。西汉是中国封建社会的第一个鼎盛时期，张骞出使西域开辟了丝绸之路，设立西域都护府。', '["刘邦建立汉朝","文景之治","汉武帝时期的盛世","张骞出使西域","设立西域都护府"]', '长安（今陕西西安）', '全国', '汉族', '汉高祖刘邦', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '西汉疆域在秦朝的基础上有所扩大，西至中亚地区，南至越南中部，北至蒙古高原南部。', 19, 1),
('xin', '新朝', '公元9年-公元23年', 'imperial', 'qin-han', 1, '王莽建立的朝代，介于西汉和东汉之间，推行了一系列改革措施，但很快灭亡。', '["王莽篡汉","推行新政","绿林赤眉起义"]', '长安（今陕西西安）', '全国', '汉族', '建兴帝王莽', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '新朝疆域基本继承西汉，但统治时间短暂。', 20, 1),
('eastern-han', '东汉', '公元25年-公元220年', 'imperial', 'qin-han', 1, '汉朝的后半期，由刘秀建立。东汉时期佛教传入中国，蔡伦改进造纸术，科技文化取得显著成就。', '["光武帝刘秀建立东汉","明章之治","蔡伦改进造纸术","佛教传入中国","班超经营西域"]', '洛阳（今河南洛阳）', '全国', '汉族', '汉光武帝刘秀', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '东汉疆域与西汉相当，但后期逐渐衰落。', 21, 1),
('cao-wei', '曹魏', '公元220年-公元265年', 'imperial', 'three-kingdoms-jin', 0, '三国时期北方的政权，由曹丕建立。曹魏是三国中实力最强的国家。', '["曹丕篡汉建魏","九品中正制","屯田制"]', '洛阳（今河南洛阳）', '北方中原', '汉族', '魏文帝曹丕', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '曹魏占据北方广大地区，是三国中疆域最大的国家。', 22, 1),
('shu-han', '蜀汉', '公元221年-公元263年', 'imperial', 'three-kingdoms-jin', 0, '三国时期西南的政权，由刘备建立。蜀汉以兴复汉室为号召。', '["刘备称帝","诸葛亮治蜀","六出祁山","鞠躬尽瘁"]', '成都（今四川成都）', '四川、云南、贵州', '汉族', '昭烈帝刘备', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '蜀汉占据西南地区，地势险要。', 23, 1),
('eastern-wu', '东吴', '公元229年-公元280年', 'imperial', 'three-kingdoms-jin', 0, '三国时期东南的政权，由孙权建立。东吴开发江南，发展海上贸易。', '["孙权称帝","开发江南","派卫温到达夷洲","赤壁之战"]', '建业（今江苏南京）', '江南地区', '汉族', '吴大帝孙权', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '东吴占据长江中下游及东南沿海地区。', 24, 1),
('western-jin', '西晋', '公元266年-公元316年', 'imperial', 'three-kingdoms-jin', 1, '晋朝的前半期，由司马炎建立。西晋短暂统一了三国，但很快陷入内乱。', '["司马炎建立晋朝","灭吴统一","八王之乱","永嘉之乱"]', '洛阳（今河南洛阳）', '全国', '汉族', '晋武帝司马炎', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '西晋统一了全国，但统治时间短暂。', 25, 1),
('eastern-jin', '东晋', '公元317年-公元420年', 'imperial', 'three-kingdoms-jin', 0, '晋朝的后半期，司马睿南迁后建立。东晋偏安江南，北方陷入五胡十六国的混乱。', '["司马睿建立东晋","王导辅政","淝水之战","门阀政治"]', '建康（今江苏南京）', '江南地区', '汉族', '晋元帝司马睿', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '东晋偏安江南，北方陷入五胡十六国的混乱。', 26, 1),
('sixteen-kingdoms', '十六国', '304年-439年', 'imperial', 'five-hus-sixteen-kingdoms', 0, '北方少数民族建立的多个政权并立时期，包括前赵、后赵、前秦、后秦、西秦、南凉、北凉、西凉、前燕、后燕、南燕、北燕、前凉、后凉、夏、成汉等。', '["五胡乱华","前秦统一北方","淝水之战","北魏统一北方"]', '多个政权各有都城', '北方地区', '匈奴、鲜卑、羯、氐、羌等', '刘渊等', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '十六国时期北方政权林立，战乱频繁。', 27, 1),
