('five-later-liang', '后梁', '公元907年-公元923年', 'imperial', 'five-dynasties', 0, '五代的第一个朝代，由朱温建立。', '["朱温称帝","与李克用对峙","被后唐所灭"]', '汴（今河南开封）', '中原地区', '汉族', '后梁太祖朱温', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后梁占据中原地区。', 56, 1),
('later-tang', '后唐', '公元923年-公元936年', 'imperial', 'five-dynasties', 0, '五代的第二个朝代，由李存勖建立。后唐是五代中疆域最大的朝代。', '["李存勖称帝","灭后梁","庄宗时期"]', '洛阳（今河南洛阳）', '北方地区', '沙陀族', '后唐庄宗李存勖', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后唐占据北方地区，是五代中疆域最大的朝代。', 57, 1),
('later-jin', '后晋', '公元936年-公元947年', 'imperial', 'five-dynasties', 0, '五代的第三个朝代，由石敬瑭建立。石敬瑭割让燕云十六州给契丹。', '["石敬瑭称帝","割让燕云十六州","被契丹所灭"]', '汴（今河南开封）', '中原地区', '沙陀族', '后晋高祖石敬瑭', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后晋占据中原地区。', 58, 1),
('later-han', '后汉', '公元947年-公元950年', 'imperial', 'five-dynasties', 0, '五代的第四个朝代，由刘知远建立。后汉统治时间短暂。', '["刘知远称帝","短暂统治","被后周取代"]', '汴（今河南开封）', '中原地区', '沙陀族', '后汉高祖刘知远', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后汉占据中原地区。', 59, 1),
('later-zhou', '后周', '公元951年-公元960年', 'imperial', 'five-dynasties', 0, '五代的最后一个朝代，由郭威建立。后周为北宋统一奠定了基础。', '["郭威称帝","周世宗改革","为北宋统一奠基"]', '汴（今河南开封）', '中原地区', '汉族', '后周太祖郭威', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后周占据中原地区。', 60, 1),
('former-shu', '前蜀', '公元907年-公元925年', 'imperial', 'five-dynasties', 0, '十国之一，由王建建立，位于四川地区。', '["王建称帝","据守蜀地","被后唐所灭"]', '成都（四川成都）', '四川', '汉族', '前蜀高祖王建', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '前蜀占据四川地区。', 61, 1),
('later-shu', '后蜀', '公元934年-公元965年', 'imperial', 'five-dynasties', 0, '十国之一，由孟知祥建立，位于四川地区。', '["孟知祥称帝","据守蜀地","被北宋所灭"]', '成都（四川成都）', '四川', '汉族', '后蜀高祖孟知祥', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '后蜀占据四川地区。', 62, 1),
('yang-wu', '南吴', '公元908年-公元937年', 'imperial', 'five-dynasties', 0, '十国之一，由杨行密建立，位于江淮地区。', '["杨行密据江淮","被南唐取代"]', '扬州（江苏扬州）', '江淮地区', '汉族', '南吴宣帝杨隆演', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '南吴占据江淮地区。', 63, 1),
('southern-tang', '南唐', '公元937年-公元975年', 'imperial', 'five-dynasties', 0, '十国之一，由李昪建立，位于江南地区。南唐文化繁荣，是十国中最强盛的国家。', '["李昪称帝","文化繁荣","李煜词坛","被北宋所灭"]', '江宁（江苏南京）、南昌（江西南昌）', '江南地区', '汉族', '南唐烈祖李昪', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '南唐占据江南地区，是十国中最强盛的国家。', 64, 1),
('wu-yue', '吴越', '公元907年-公元978年', 'imperial', 'five-dynasties', 0, '十国之一，由钱镠建立，位于浙江地区。吴越国经济繁荣，文化发达。', '["钱镠据浙江","保境安民","纳土归宋"]', '杭州（浙江杭州）', '浙江', '汉族', '吴越武肃王钱镠', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '吴越占据浙江地区。', 65, 1),
('min', '闽', '公元909年-公元945年', 'imperial', 'five-dynasties', 0, '十国之一，由王审知建立，位于福建地区。', '["王审知据福建","开发闽地","被南唐所灭"]', '长乐（福建福州）、建州（福建建瓯）', '福建', '汉族', '闽太祖王审知', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '闽国占据福建地区。', 66, 1),
('ma-chu', '南楚', '公元907年-公元951年', 'imperial', 'five-dynasties', 0, '十国之一，由马殷建立，位于湖南地区。', '["马殷据湖南","发展茶业","被南唐所灭"]', '潭州（湖南长沙）', '湖南', '汉族', '楚武穆王马殷', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '南楚占据湖南地区。', 67, 1),
('southern-han', '南汉', '公元917年-公元971年', 'imperial', 'five-dynasties', 0, '十国之一，由刘隐建立，位于广东地区。', '["刘隐据岭南","开发广东","被北宋所灭"]', '番禺（广东广州）', '广东', '汉族', '南汉高祖刘䶮', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '南汉占据广东地区。', 68, 1),
('jingnan', '荆南（南平）', '公元924年-公元963年', 'imperial', 'five-dynasties', 0, '十国之一，由高季兴建立，位于湖北地区。荆南是十国中最小的国家。', '["高季兴据荆南","夹缝生存","纳土归宋"]', '荆州（湖北江陵）', '湖北', '汉族', '荆南武兴王高季兴', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '荆南占据湖北地区，是十国中最小的国家。', 69, 1),
('northern-han', '北汉', '公元951年-公元979年', 'imperial', 'five-dynasties', 0, '十国之一，由刘崇建立，位于山西地区。北汉是十国中唯一在北方的国家。', '["刘崇据太原","依附契丹","被北宋所灭"]', '晋阳（山西太原）', '山西', '汉族', '北汉世祖刘崇', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '北汉占据山西地区，是十国中唯一在北方的国家。', 70, 1),
('northern-song', '北宋', '公元960年-公元1127年', 'imperial', 'song-liao-xia-jin', 1, '宋朝的前半期，由赵匡胤建立。北宋统一了中原地区，但北方有辽、西夏等政权并立。', '["赵匡胤陈桥兵变","杯酒释兵权","王安石变法","活字印刷术"]', '东京（今河南开封）', '中原地区', '汉族', '宋太祖赵匡胤', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '北宋统一了中原地区，但北方有辽、西夏等政权并立。', 71, 1),
('southern-song', '南宋', '公元1127年-公元1279年', 'imperial', 'song-liao-xia-jin', 0, '宋朝的后半期，赵构南迁后建立。南宋偏安江南，北方被金国占据。', '["赵构建立南宋","岳飞抗金","绍兴和议","崖山海战"]', '临安（今浙江杭州）', '江南地区', '汉族', '宋高宗赵构', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '南宋偏安江南，北方被金国占据。', 72, 1),
('liao', '辽朝', '公元916年-公元1125年', 'imperial', 'song-liao-xia-jin', 0, '中国历史上由契丹族建立的朝代，与北宋并立，疆域辽阔。', '["耶律阿保机建立辽朝","澶渊之盟","辽道宗时期的繁荣","被金所灭"]', '上京（今内蒙古巴林左旗南）', '北方草原', '契丹族', '太祖耶律阿保机', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '辽朝疆域东至日本海，西至阿尔泰山，北至外兴安岭，南至河北中部。', 73, 1),
('western-xia', '西夏', '公元1038年-公元1227年', 'imperial', 'song-liao-xia-jin', 0, '中国历史上由党项族建立的朝代，位于西北地区。', '["李元昊称帝","创制西夏文","好水川之战","被蒙古所灭"]', '兴庆（今宁夏银川）', '宁夏、甘肃、陕西', '党项族', '景宗李元昊', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '西夏占据西北地区。', 74, 1),
('jurchen-jin', '金朝', '公元1115年-公元1234年', 'imperial', 'song-liao-xia-jin', 0, '中国历史上由女真族建立的朝代，灭辽和北宋，与南宋对峙。', '["完颜阿骨打建立金朝","靖康之变","岳飞抗金","被蒙古所灭"]', '会宁（阿城，今黑龙江省哈尔滨市）、中都（今北京市）、开封（今河南开封）', '北方地区', '女真族', '金太祖完颜阿骨打', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '金朝疆域东至日本海，西至陕西，北至外兴安岭，南至淮河一线。', 75, 1),
('yuan', '元朝', '公元1271年-公元1368年', 'imperial', 'yuan-ming-qing', 1, '中国历史上第一个由少数民族建立的大一统王朝，由蒙古族的忽必烈建立。元朝是中国历史上疆域最大的朝代之一。', '["忽必烈建立元朝","统一中国","开通海上丝绸之路","马可·波罗来华"]', '大都（今北京）', '全国', '蒙古族', '元世祖忽必烈', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '元朝疆域东至朝鲜半岛，西至中亚地区，南至南海，北至西伯利亚南部，是中国历史上疆域最大的朝代。', 76, 1),
('ming', '明朝', '公元1368年-公元1644年', 'imperial', 'yuan-ming-qing', 1, '中国历史上最后一个由汉族建立的大一统王朝，由朱元璋建立。明朝是中国封建社会后期的鼎盛时期，郑和下西洋促进了中外交流。', '["朱元璋建立明朝","郑和下西洋","永乐大典的编纂","戚继光抗倭"]', '南京（江苏南京）、北京（今北京市）', '全国', '汉族', '明太祖朱元璋', 'https://images.unsplash.com/photo-1557862921-37829c790f19?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '明朝疆域东至朝鲜半岛，西至嘉峪关，南至南海，北至长城一线。', 77, 1),
('qing', '清朝', '公元1616年-公元1912年', 'imperial', 'yuan-ming-qing', 1, '中国历史上最后一个封建王朝，由满族建立。清朝是中国封建社会的最后一个鼎盛时期，康乾盛世是中国封建社会的最后一个盛世。', '["努尔哈赤建立后金","清军入关","康乾盛世","四库全书的编纂"]', '盛京（今辽宁沈阳）、北京', '全国', '满族', '清太宗皇太极', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '清朝疆域东至库页岛，西至葱岭，南至南海诸岛，北至外兴安岭，是中国历史上疆域较大的朝代之一。', 78, 1);

