-- ============================================
DELETE FROM `historical_event`;
INSERT INTO `historical_event` (
  `event_id`, `title`, `period`, `category`, `brief`, `description`,
  `impact`, `image_url`, `tags`, `sort_order`, `is_active`
) VALUES
('xia-establishment', '夏朝建立', '约前2070年', 'political', '禹建立中国历史上第一个世袭制朝代，标志着中国进入国家社会。', '夏朝是中国历史上第一个世袭制朝代，由禹建立。禹因治水有功，被舜禅让为天子，后禹的儿子启继位，确立了世袭制，结束了原始社会的禅让制。夏朝的建立标志着中国进入了国家社会，是中国历史的重要里程碑。', '夏朝的建立标志着中国进入了国家社会，确立了世袭制，为后世朝代的发展奠定了基础。', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["夏朝","禹","世袭制"]', 0, 1),
('shang-dynasty', '商朝建立', '约前1600年', 'political', '商汤灭夏，建立商朝，中国进入青铜器时代的鼎盛时期。', '商朝是中国历史上第二个朝代，由商汤建立。商汤率领商部落推翻了夏朝的统治，建立了商朝。商朝是中国青铜器时代的鼎盛时期，甲骨文的使用标志着中国文字的正式形成。商朝的政治、经济、文化都有了很大的发展。', '商朝的建立标志着中国进入了青铜器时代的鼎盛时期，甲骨文的使用标志着中国文字的正式形成。', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["商朝","商汤","青铜器"]', 1, 1),
('zhou-establishment', '周朝建立', '前1046年', 'political', '周武王灭商，建立周朝，确立了分封制和宗法制。', '周朝是中国历史上最长的朝代，由周武王姬发建立。周武王率领周部落推翻了商朝的统治，建立了周朝。周朝确立了分封制和宗法制，是中国古代礼乐文明的鼎盛时期。周朝分为西周和东周两个时期，东周又分为春秋和战国两个阶段。', '周朝确立了分封制和宗法制，是中国古代礼乐文明的鼎盛时期，对后世中国的政治制度产生了深远影响。', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["周朝","周武王","分封制"]', 2, 1),
('qin-unification', '秦统一六国', '前221年', 'political', '秦始皇嬴政统一六国，建立中国历史上第一个统一的多民族的中央集权国家。', '秦始皇嬴政是中国历史上第一个皇帝，他通过十年的战争，先后灭掉了韩、赵、魏、楚、燕、齐六国，统一了中国。秦始皇统一六国后，实行了一系列的改革，包括统一文字、货币、度量衡，实行郡县制，修建万里长城等。', '秦统一六国标志着中国进入了中央集权的封建社会，统一文字、货币、度量衡等措施促进了中国的统一和发展。', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["秦朝","秦始皇","统一六国"]', 3, 1),
('han-establishment', '汉朝建立', '前202年', 'political', '刘邦建立汉朝，中国进入封建社会的第一个鼎盛时期。', '汉朝是中国历史上继秦朝之后的大一统王朝，由刘邦建立。汉朝分为西汉和东汉两个时期，是中国封建社会的第一个鼎盛时期。汉武帝时期，汉朝的国力达到了顶峰，张骞出使西域开辟了丝绸之路，促进了中外交流。', '汉朝是中国封建社会的第一个鼎盛时期，张骞出使西域开辟了丝绸之路，促进了中外交流，对后世中国的发展产生了深远影响。', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["汉朝","刘邦","丝绸之路"]', 4, 1),
('three-kingdoms', '三国鼎立', '220年-280年', 'political', '魏、蜀、吴三国鼎立，中国历史进入三国时期。', '三国时期是中国历史上继东汉之后的一个分裂时期，魏、蜀、吴三国鼎立。三国时期英雄辈出，如曹操、刘备、孙权、诸葛亮、关羽、张飞等，是中国历史上最具传奇色彩的时期之一。', '三国时期是中国历史上的重要分裂时期，英雄辈出，对后世文学、艺术产生了深远影响。', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["三国","曹操","刘备","孙权"]', 5, 1),
('tang-establishment', '唐朝建立', '618年', 'political', '李渊建立唐朝，中国进入封建社会的鼎盛时期。', '唐朝是中国历史上最强盛的朝代之一，由李渊建立。唐朝是中国封建社会的鼎盛时期，政治开明，经济繁荣，文化昌盛，对外交流频繁。唐太宗贞观之治和唐玄宗开元盛世是唐朝的鼎盛时期。', '唐朝是中国封建社会的鼎盛时期，政治开明，经济繁荣，文化昌盛，对外交流频繁，是中国历史上的黄金时代。', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["唐朝","李渊","贞观之治"]', 6, 1),
('song-establishment', '宋朝建立', '960年', 'political', '赵匡胤建立宋朝，中国进入封建社会经济、科技、文化高度发达的时期。', '宋朝是中国历史上继唐朝之后的大一统王朝，由赵匡胤建立。宋朝分为北宋和南宋两个时期，是中国封建社会经济、科技、文化高度发达的时期。宋朝的农业、手工业、商业都有了很大的发展，科技发明如活字印刷术、指南针、火药等对世界文明的发展产生了深远影响。', '宋朝是中国封建社会经济、科技、文化高度发达的时期，科技发明如活字印刷术、指南针、火药等对世界文明的发展产生了深远影响。', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["宋朝","赵匡胤","活字印刷术"]', 7, 1),
('yuan-establishment', '元朝建立', '1271年', 'political', '忽必烈建立元朝，中国历史上第一个由少数民族建立的大一统王朝。', '元朝是中国历史上第一个由少数民族建立的大一统王朝，由蒙古族的忽必烈建立。元朝是中国历史上疆域最大的朝代之一，统一了中国，开通了海上丝绸之路，促进了中外交流。马可·波罗来华是元朝中外交流的重要事件。', '元朝是中国历史上第一个由少数民族建立的大一统王朝，疆域辽阔，促进了中外交流。', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["元朝","忽必烈","马可·波罗"]', 8, 1),
('ming-establishment', '明朝建立', '1368年', 'political', '朱元璋建立明朝，中国历史上最后一个由汉族建立的大一统王朝。', '明朝是中国历史上最后一个由汉族建立的大一统王朝，由朱元璋建立。明朝是中国封建社会后期的鼎盛时期，郑和下西洋促进了中外交流，永乐大典的编纂是中国文化的重要成就。', '明朝是中国历史上最后一个由汉族建立的大一统王朝，郑和下西洋促进了中外交流，永乐大典的编纂是中国文化的重要成就。', 'https://images.unsplash.com/photo-1557862921-37829c790f19?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["明朝","朱元璋","郑和下西洋"]', 9, 1),
('qing-establishment', '清朝建立', '1644年', 'political', '清军入关，建立清朝，中国历史上最后一个封建王朝。', '清朝是中国历史上最后一个封建王朝，由满族建立。清军入关后，逐步统一了中国。清朝是中国封建社会的最后一个鼎盛时期，康乾盛世是中国封建社会的最后一个盛世。四库全书的编纂是中国文化的重要成就。', '清朝是中国历史上最后一个封建王朝，康乾盛世是中国封建社会的最后一个盛世，四库全书的编纂是中国文化的重要成就。', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["清朝","清军入关","康乾盛世"]', 10, 1),
('xinhai-revolution', '辛亥革命', '1911年', 'political', '孙中山领导的辛亥革命推翻清朝统治，建立中华民国。', '辛亥革命是中国近代史上的重要事件，由孙中山领导的革命党人发动。辛亥革命推翻了清朝的统治，结束了中国两千多年的封建帝制，建立了中华民国。辛亥革命是中国从封建社会向现代社会过渡的重要里程碑。', '辛亥革命推翻了清朝的统治，结束了中国两千多年的封建帝制，建立了中华民国，是中国从封建社会向现代社会过渡的重要里程碑。', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["辛亥革命","孙中山","中华民国"]', 11, 1),
('may-fourth-movement', '五四运动', '1919年', 'cultural', '五四运动爆发，标志着中国新民主主义革命的开始。', '五四运动是中国近代史上的重要事件，1919年5月4日，北京学生举行游行示威，抗议巴黎和会上中国外交的失败。五四运动是中国新民主主义革命的开始，促进了马克思主义在中国的传播，为中国共产党的成立奠定了思想基础。', '五四运动是中国新民主主义革命的开始，促进了马克思主义在中国的传播，为中国共产党的成立奠定了思想基础。', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["五四运动","新民主主义革命","马克思主义"]', 12, 1),
('prc-establishment', '中华人民共和国成立', '1949年', 'political', '中华人民共和国成立，中国进入社会主义建设时期。', '1949年10月1日，毛泽东在天安门城楼上庄严宣告中华人民共和国成立。中华人民共和国的成立标志着中国人民从此站立起来了，中国进入了社会主义建设时期。经过改革开放，中国逐渐发展成为世界第二大经济体。', '中华人民共和国的成立标志着中国人民从此站立起来了，中国进入了社会主义建设时期，经过改革开放，中国逐渐发展成为世界第二大经济体。', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', '["中华人民共和国","毛泽东","改革开放"]', 13, 1);

