DELETE FROM `historical_figure`;
INSERT INTO `historical_figure` (
  `figure_id`, `name`, `dynasty`, `category`, `title`, `brief`, `description`,
  `achievements`, `quotes`, `portrait_url`, `tags`,
  `back_era`, `back_contribution`, `back_influence`, `back_fun_fact`, `back_related_figures`,
  `representative_works`, `evaluation_tags`,
  `sort_order`, `is_active`
) VALUES
('confucius', '孔子', '春秋时期', 'philosophy', '思想家、教育家', '儒家学派创始人，被后世尊称为"至圣先师"。', '孔子（前551年-前479年），名丘，字仲尼，春秋时期鲁国陬邑（今山东曲阜）人。孔子是中国古代著名的思想家、教育家，儒家学派的创始人。他提出了"仁"的核心思想，主张"仁者爱人"，强调道德修养和社会责任。孔子的教育思想强调"有教无类"，认为每个人都有接受教育的权利。他的思想对中国乃至东亚文化圈产生了深远的影响。', '["创立儒家学派","提出\\"仁\\"的核心思想","编撰六经","培养了三千弟子，七十二贤人"]', '己所不欲，勿施于人。', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["儒家","思想家","教育家"]', '春秋末期', '创立儒家学说，奠定中华伦理道德基础', '影响中国两千多年，被尊为"万世师表"', '孔子身高九尺六寸，约合今天1.9米', '["孟子","荀子","颜回"]', '《论语》《春秋》', '["万世师表","儒家始祖","思想家","教育家"]', 0, 1),
('laozi', '老子', '春秋时期', 'philosophy', '思想家、道家学派创始人', '道家学派创始人，著有《道德经》。', '老子（约前571年-约前471年），姓李，名耳，字聃，春秋时期楚国人。老子是中国古代著名的思想家，道家学派的创始人。他提出了"道"的核心思想，主张"道法自然"，强调顺应自然，无为而治。老子的著作《道德经》是道家学派的经典，对中国哲学、宗教、文化产生了深远的影响。', '["创立道家学派","著有《道德经》","提出\\"道\\"的核心思想","主张\\"无为而治\\""]', '道可道，非常道；名可名，非常名。', 'https://images.unsplash.com/photo-15187092688054-89e3c9298b7b?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["道家","思想家","道德经"]', '春秋末期', '创立道家学说，著《道德经》五千言', '与儒家并称中华思想两大支柱', '传说老子骑青牛出函谷关，不知所终', '["庄子","列子","文子"]', '《道德经》', '["道家始祖","哲学宗师","智者","先贤"]', 1, 1),
('qinshihuang', '秦始皇', '秦朝', 'politics', '中国历史上第一个皇帝', '统一六国，建立中国历史上第一个中央集权国家。', '秦始皇（前259年-前210年），嬴姓，赵氏，名政，秦庄襄王之子。秦始皇是中国历史上第一个皇帝，他通过十年的战争，先后灭掉了韩、赵、魏、楚、燕、齐六国，统一了中国。秦始皇统一六国后，实行了一系列的改革，包括统一文字、货币、度量衡，实行郡县制，修建万里长城等。他的统一措施对中国历史的发展产生了深远的影响。', '["统一六国","建立中央集权制度","统一文字、货币、度量衡","修建万里长城","实行郡县制"]', '朕为始皇帝，后世以计数，二世、三世至于万世，传之无穷。', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["秦朝","统一六国","皇帝"]', '公元前221-210年', '统一中国，建立中央集权制度', '奠定中国两千多年政治制度基本格局', '秦始皇陵兵马俑被誉为"世界第八大奇迹"', '["李斯","蒙恬","赵高"]', '统一度量衡、书同文', '["千古一帝","统一者","改革家","雄才大略"]', 2, 1),
('hanwudi', '汉武帝', '西汉', 'politics', '西汉皇帝', '西汉的鼎盛时期，开辟丝绸之路。', '汉武帝（前156年-前87年），刘彻，西汉第七位皇帝。汉武帝是中国历史上著名的皇帝之一，他在位期间，西汉的国力达到了顶峰。汉武帝推行了一系列的改革，包括推行推恩令，削弱诸侯王的势力；实行盐铁专卖，增加国家财政收入；设立太学，培养人才。他还派遣张骞出使西域，开辟了丝绸之路，促进了中外交流。', '["推行推恩令","实行盐铁专卖","设立太学","派遣张骞出使西域，开辟丝绸之路","击败匈奴"]', '犯我强汉者，虽远必诛。', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["西汉","汉武帝","丝绸之路"]', '公元前141-87年', '开辟丝绸之路，奠定汉朝强盛基础', '\'汉人\'族称由此而来', '汉武帝一生有六位皇后，却无一人善终', '["卫青","霍去病","张骞","司马迁"]', '推恩令、盐铁专卖', '["雄才大略","开疆拓土","明君","改革者"]', 3, 1),
('zhugeliang', '诸葛亮', '三国时期', 'politics', '蜀汉丞相', '杰出的政治家、军事家，被后世尊称为"武侯"。', '诸葛亮（181年-234年），字孔明，号卧龙，三国时期蜀汉丞相。诸葛亮是中国历史上著名的政治家、军事家，他辅佐刘备建立了蜀汉政权，后又辅佐刘禅治理国家。诸葛亮一生鞠躬尽瘁，死而后已，他的智慧和忠诚被后世广为传颂。诸葛亮著有《出师表》等著作，他的军事思想对后世产生了深远的影响。', '["辅佐刘备建立蜀汉政权","六出祁山，北伐中原","发明木牛流马","著有《出师表》","治理蜀汉，发展经济"]', '鞠躬尽瘁，死而后已。', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["三国","诸葛亮","政治家","军事家"]', '公元181-234年', '辅佐刘备建立蜀汉，鞠躬尽瘁', '智慧与忠诚的化身，后世景仰', '诸葛亮发明的\'孔明灯\'是世界上最早的热气球', '["刘备","关羽","张飞","司马懿"]', '《出师表》《诫子书》', '["智慧化身","忠臣","军事家","政治家"]', 4, 1),
('taizong', '唐太宗', '唐朝', 'politics', '唐朝皇帝', '贞观之治的开创者，唐朝的鼎盛时期。', '唐太宗（598年-649年），李世民，唐朝第二位皇帝。唐太宗是中国历史上著名的皇帝之一，他在位期间，实行了一系列的改革，包括任用贤能，虚心纳谏；轻徭薄赋，发展经济；完善科举制度，选拔人才。唐太宗的统治时期被称为"贞观之治"，是中国封建社会的鼎盛时期之一。', '["开创贞观之治","任用贤能，虚心纳谏","完善科举制度","击败东突厥","促进中外交流"]', '以铜为镜，可以正衣冠；以古为镜，可以知兴替；以人为镜，可以明得失。', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["唐朝","唐太宗","贞观之治"]', '公元626-649年', '开创贞观之治，奠定唐朝盛世基础', '被后世誉为千古一帝，为盛唐气象奠定基础', '唐太宗李世民是中国历史上最善于纳谏的皇帝之一', '["魏征","房玄龄","杜如晦","长孙无忌"]', '贞观之治', '["明君典范","贞观之治","纳谏如流","文治武功"]', 5, 1),
('libai', '李白', '唐朝', 'culture', '诗人', '唐代伟大的浪漫主义诗人，被后世尊称为"诗仙"。', '李白（701年-762年），字太白，号青莲居士，唐代伟大的浪漫主义诗人。李白的诗歌想象丰富，语言豪放，风格浪漫，被后世尊称为"诗仙"。他的诗歌题材广泛，包括山水田园、边塞战争、饮酒作乐等。李白的代表作有《将进酒》、《望庐山瀑布》、《蜀道难》等。', '["创作了大量优秀的诗歌","开创了浪漫主义诗歌流派","对后世诗歌产生了深远的影响","与杜甫并称为\\"李杜\\""]', '天生我材必有用，千金散尽还复来。', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["唐朝","诗人","诗仙"]', '公元701-762年', '创作大量浪漫主义诗歌，开创唐诗高峰', '被后世尊为\'诗仙\'，对中国诗歌发展影响深远', '李白好饮酒，有\'斗酒诗百篇\'的美誉', '["杜甫","贺知章","孟浩然","王维"]', '《将进酒》《蜀道难》', '["诗仙","浪漫主义","文学巨匠","酒仙"]', 6, 1),
('dufu', '杜甫', '唐朝', 'culture', '诗人', '唐代伟大的现实主义诗人，被后世尊称为"诗圣"。', '杜甫（712年-770年），字子美，号少陵野老，唐代伟大的现实主义诗人。杜甫的诗歌真实地反映了唐代社会的现实，关心民生疾苦，被后世尊称为"诗圣"。他的诗歌题材广泛，包括战争、贫困、社会不公等。杜甫的代表作有《三吏》、《三别》、《茅屋为秋风所破歌》等。', '["创作了大量优秀的现实主义诗歌","真实地反映了唐代社会的现实","对后世诗歌产生了深远的影响","与李白并称为\\"李杜\\""]', '安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山。', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["唐朝","诗人","诗圣"]', '公元712-770年', '创作大量现实主义诗歌，反映社会现实', '被后世尊为\'诗圣\'，其诗被称为\'诗史\'', '杜甫与李白并称为\'李杜\'，是唐代最伟大的诗人之一', '["李白","王维","岑参","高适"]', '《三吏》《三别》', '["诗圣","现实主义","文学巨匠","忧国忧民"]', 7, 1),
('zhaozhongjing', '张仲景', '东汉', 'science', '医学家', '被后世尊称为"医圣"，著有《伤寒杂病论》。', '张仲景（约150年-约215年），名机，字仲景，东汉末年著名的医学家。张仲景被后世尊称为"医圣"，他著有《伤寒杂病论》，系统地总结了汉代以前的医学经验，确立了中医辨证论治的理论体系。张仲景的医学思想对后世中医的发展产生了深远的影响。', '["著有《伤寒杂病论》","确立了中医辨证论治的理论体系","对后世中医的发展产生了深远的影响","被后世尊称为\\"医圣\\""]', '勤求古训，博采众方。', 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["东汉","医学家","医圣"]', '约公元150-215年', '著《伤寒杂病论》，确立中医辨证论治体系', '被后世尊为\'医圣\'，奠定中医理论基础', '张仲景被称为\'医中之圣，方中之祖\'', '["华佗","扁鹊","孙思邈","李时珍"]', '《伤寒杂病论》', '["医圣","医学宗师","方祖","济世救人"]', 8, 1),
('shenkuo', '沈括', '北宋', 'science', '科学家、政治家', '著有《梦溪笔谈》，百科全书式的科学家。', '沈括（1031年-1095年），字存中，号梦溪丈人，北宋时期著名的科学家、政治家。沈括是中国历史上罕见的百科全书式的科学家，他的著作《梦溪笔谈》涵盖了数学、物理、化学、天文、地理、生物、医学等多个领域的知识。沈括在科学技术方面有很多发明和发现，如改进指南针、发现磁偏角等。', '["著有《梦溪笔谈》","改进指南针","发现磁偏角","在数学、物理、化学、天文等多个领域有重要贡献"]', '格物致知，实事求是。', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["北宋","科学家","梦溪笔谈"]', '公元1031-1095年', '著《梦溪笔谈》，百科全书式科学著作', '被称为中国科学史上的里程碑', '沈括最早发现了磁偏角现象', '["郭守敬","张衡","祖冲之","徐光启"]', '《梦溪笔谈》', '["科学巨匠","博学家","发明家","学者"]', 9, 1),
('zhaozong', '宋太祖', '北宋', 'politics', '北宋开国皇帝', '陈桥兵变黄袍加身，建立北宋。', '宋太祖（927年-976年），赵匡胤，北宋开国皇帝。赵匡胤原是后周的将领，960年，他在陈桥驿发动兵变，黄袍加身，建立了北宋政权。赵匡胤在位期间，采取了一系列的措施，加强中央集权，结束了五代十国的分裂局面。他还实行了"重文轻武"的政策，促进了宋代文化的繁荣。', '["建立北宋政权","结束五代十国的分裂局面","加强中央集权","实行\\"重文轻武\\"的政策"]', '卧榻之侧，岂容他人鼾睡。', 'https://images.unsplash.com/photo-1504257432389-52343af06ae3?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["北宋","赵匡胤","开国皇帝"]', '公元927-976年', '建立北宋，结束五代十国分裂局面', '实行重文轻武政策，促进宋代文化繁荣', '陈桥兵变黄袍加身，建立北宋政权', '["赵光义","赵普","石守信","高怀德"]', '建立北宋', '["开国皇帝","军事家","政治家","改革者"]', 10, 1),
('kangxi', '康熙皇帝', '清朝', 'politics', '清朝皇帝', '康乾盛世的开创者，中国历史上在位时间最长的皇帝。', '康熙皇帝（1654年-1722年），爱新觉罗·玄烨，清朝第四位皇帝。康熙皇帝是中国历史上在位时间最长的皇帝，他在位61年。康熙皇帝在位期间，实行了一系列的改革，包括平定三藩之乱，收复台湾，抗击沙俄侵略，加强对边疆地区的管理。他还重视文化教育，组织编纂了《康熙字典》等大型文化工程。康熙皇帝的统治时期是清朝的鼎盛时期，被称为"康乾盛世"。', '["平定三藩之乱","收复台湾","抗击沙俄侵略","加强对边疆地区的管理","组织编纂《康熙字典》"]', '天下兴亡，匹夫有责。', 'https://images.unsplash.com/photo-1463453091185-615462dcce3c?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["清朝","康熙","康乾盛世"]', '公元1654-1722年', '开创康乾盛世，巩固清朝统治', '中国历史上在位时间最长的皇帝', '康熙皇帝在位61年，是中国历史上在位时间最长的皇帝', '["雍正皇帝","乾隆皇帝","鳌拜","吴三桂"]', '《康熙字典》', '["圣祖","明君","文治武功","博学多才"]', 11, 1),
('sunyatsen', '孙中山', '近代', 'politics', '革命家、政治家', '中华民国的缔造者，被后世尊称为"国父"。', '孙中山（1866年-1925年），名文，字载之，号逸仙，近代中国伟大的革命家、政治家。孙中山是中华民国的缔造者，他领导的辛亥革命推翻了清朝的统治，结束了中国两千多年的封建帝制，建立了中华民国。孙中山提出了"三民主义"（民族、民权、民生）的政治纲领，主张建立一个民主、自由、平等的新中国。孙中山被后世尊称为"国父"。', '["领导辛亥革命，推翻清朝统治","建立中华民国","提出\\"三民主义\\"的政治纲领","为中国的民主革命事业做出了杰出贡献"]', '革命尚未成功，同志仍需努力。', 'https://images.unsplash.com/photo-1557862921-37829c790f19?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["近代","革命家","国父"]', '公元1866-1925年', '领导辛亥革命，推翻清朝统治，建立中华民国', '被后世尊为\'国父\'，中国民主革命的先行者', '孙中山提出\'三民主义\'，主张民族、民权、民生', '["黄兴","宋教仁","廖仲恺","宋庆龄"]', '三民主义', '["国父","革命家","先行者","民主先驱"]', 12, 1);

