-- ============================================
DELETE FROM `cultural_heritage`;
INSERT INTO `cultural_heritage` (
  `heritage_id`, `name`, `location`, `category`, `era`, `year`, `brief`,
  `description`, `history`, `cultural_significance`, `features`, `related_figures`,
  `image_url`, `thumbnail_url`, `images`, `related_items`, `sort_order`, `is_active`
) VALUES
('great-wall', '长城', '中国北部', 'site', '春秋战国-明', '公元前7世纪-公元17世纪', '中国古代伟大的防御工程，世界文化遗产。', '长城是中国古代伟大的防御工程，也是世界上最伟大的建筑之一。长城始建于春秋战国时期，秦统一六国后，秦始皇将各国的长城连接起来，形成了万里长城。此后，历代王朝都对长城进行了修缮和扩建。长城的主要作用是防御北方游牧民族的入侵，它是中国古代劳动人民智慧和勇气的结晶。1987年，长城被联合国教科文组织列为世界文化遗产。', '长城的修筑历史可上溯到西周时期，发生在首都镐京（今陕西西安）的著名典故"烽火戏诸侯"就源于此。春秋战国时期列国争霸，互相防守，长城修筑进入第一个高潮，但此时修筑的长度都比较短。秦灭六国统一天下后，秦始皇连接和修缮战国长城，始有万里长城之称。', '长城是中华民族的象征，也是人类文明史上最伟大的建筑工程之一。它体现了中国古代人民的智慧、勇气和毅力，是中国历史文化的重要载体。', '["世界上最长的防御工程","中国古代劳动人民智慧和勇气的结晶","中国古代军事防御体系的重要组成部分","世界文化遗产"]', '["秦始皇","蒙恬","戚继光"]', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1508804185872-d7badad00f7d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["forbidden-city","terracotta-army","potala-palace"]', 0, 1),
('forbidden-city', '故宫', '北京市', 'building', '明-清', '1406年-1420年', '中国明清两代的皇家宫殿，世界文化遗产。', '故宫又称紫禁城，是中国明清两代的皇家宫殿，位于北京市中心。故宫始建于明永乐四年（1406年），永乐十八年（1420年）建成。故宫是中国古代宫廷建筑的精华，也是世界上现存规模最大、保存最为完整的木质结构古建筑之一。故宫占地面积约72万平方米，建筑面积约15万平方米，有大小宫殿七十多座，房屋九千余间。', '故宫于明成祖永乐四年（1406年）开始建设，以南京故宫为蓝本营建，到永乐十八年（1420年）建成。它是一座长方形城池，南北长961米，东西宽753米，四面围有高10米的城墙，城外有宽52米的护城河。', '故宫是中国古代宫廷建筑的精华，体现了中国古代皇家建筑的威严和气势。它不仅是明清两代的政治中心，也是中国传统文化的重要载体。', '["世界上现存规模最大、保存最为完整的木质结构古建筑之一","中国古代宫廷建筑的精华","体现了中国古代皇家建筑的威严和气势","世界文化遗产"]', '["明成祖","康熙","乾隆"]', 'https://images.unsplash.com/photo-1580273916550-e323be2ae537?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1580273916550-e323be2ae537?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1580273916550-e323be2ae537?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["summer-palace","potala-palace","yueyang-tower"]', 1, 1),
('terracotta-army', '兵马俑', '陕西省西安市', 'artifact', '秦', '公元前246年-公元前208年', '秦始皇陵的陪葬坑，世界文化遗产。', '兵马俑，即秦始皇陵兵马俑，位于陕西省西安市临潼区秦始皇陵以东1.5公里处的兵马俑坑内。兵马俑是秦始皇陵的陪葬坑，由三个大型兵马俑坑组成，坑内排列着数千个与真人真马大小相同的陶制兵马俑。这些兵马俑形态各异，栩栩如生，是中国古代陶俑艺术的杰作。', '秦始皇陵兵马俑坑是秦始皇陵的陪葬坑，位于陵园东侧1500米处。秦始皇兵马俑陪葬坑坐西向东，三坑呈品字形排列。最早发现的是一号俑坑，呈长方形，东西长230米，南北宽62米，深约5米，总面积14260平方米。', '兵马俑的发现，为研究中国古代军事、政治、经济、文化等提供了重要的实物资料。它是中国古代陶俑艺术的杰作，也是世界考古史上的重大发现。', '["世界上最大的古代军事博物馆","中国古代陶俑艺术的杰作","为研究中国古代军事、政治、经济、文化等提供了重要的实物资料","世界文化遗产"]', '["秦始皇","李斯"]', 'https://images.unsplash.com/photo-1587790890044-4a665722283e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1587790890044-4a665722283e?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1587790890044-4a665722283e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["great-wall","dujiangyan","mogao-grottoes"]', 2, 1),
('mogao-grottoes', '莫高窟', '甘肃省敦煌市', 'site', '十六国-元', '366年-1368年', '中国古代佛教艺术宝库，世界文化遗产。', '莫高窟，俗称千佛洞，位于甘肃省敦煌市东南25公里处的鸣沙山东麓断崖上。莫高窟始建于前秦建元二年（366年），历经十六国、北朝、隋、唐、五代、西夏、元等历代的兴建，形成了规模宏大的石窟群。', '莫高窟始建于十六国时期，据唐《李克让重修莫高窟佛龛碑》一书的记载，前秦建元二年（366年），僧人乐僔路经此山，忽见金光闪耀，如现万佛，于是便在岩壁上开凿了第一个洞窟。', '莫高窟的壁画和彩塑艺术水平极高，反映了中国古代佛教艺术的发展历程，是中国古代文化艺术的瑰宝。它是中西文化交流的重要见证。', '["世界上现存规模最大、内容最丰富的佛教艺术地","中国古代佛教艺术宝库","反映了中国古代佛教艺术的发展历程","世界文化遗产"]', '["乐僔和尚","王圆箓"]', 'https://images.unsplash.com/photo-1586348943529-beaae6c28db9?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1586348943529-beaae6c28db9?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1586348943529-beaae6c28db9?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["potala-palace","jade-buddha-temple","terracotta-army"]', 3, 1),
('potala-palace', '布达拉宫', '西藏自治区拉萨市', 'building', '唐-清', '7世纪-17世纪', '藏传佛教圣地，世界文化遗产。', '布达拉宫，位于西藏自治区拉萨市城关区北京中路35号，是藏传佛教圣地，也是世界上海拔最高、规模最大的宫堡式建筑群。布达拉宫始建于公元7世纪吐蕃王朝松赞干布时期，是松赞干布为迎娶文成公主而建。', '布达拉宫依山垒砌，群楼重叠，殿宇嵯峨，气势雄伟，有横空出世、气贯苍穹之势，坚实墩厚的花岗石墙体，松茸平展的白玛草墙领，金碧辉煌的金顶，具有强烈装饰效果的巨大鎏金宝瓶、经幢和红幡，交相映辉。', '布达拉宫是藏式建筑的杰出代表，也是中华民族古建筑的精华之作。它是藏传佛教的重要圣地，也是藏汉文化交流的历史见证。', '["世界上海拔最高、规模最大的宫堡式建筑群","藏传佛教圣地","藏式建筑的杰出代表","世界文化遗产"]', '["松赞干布","文成公主","五世达赖"]', 'https://images.unsplash.com/photo-1593941707431-f326c02f3f54?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1593941707431-f326c02f3f54?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1593941707431-f326c02f3f54?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["forbidden-city","mogao-grottoes","jade-buddha-temple"]', 4, 1),
('summer-palace', '颐和园', '北京市', 'building', '清', '1750年-1764年', '中国古代皇家园林，世界文化遗产。', '颐和园，位于北京市海淀区新建宫门路19号，是中国古代皇家园林，也是世界上现存规模最大、保存最完整的皇家园林之一。颐和园始建于清朝乾隆年间，原名清漪园，是乾隆皇帝为庆祝母亲寿辰而建。', '颐和园前身为清漪园，坐落在北京西郊，距城区15公里，占地约290公顷，与圆明园毗邻。它是以昆明湖、万寿山为基址，以杭州西湖为蓝本，汲取江南园林的设计手法而建成的一座大型山水园林，被誉为"皇家园林博物馆"。', '颐和园是中国古典园林艺术的杰作，也是世界文化遗产中的瑰宝。它体现了中国古代园林艺术的最高成就，是中国传统文化的重要载体。', '["世界上现存规模最大、保存最完整的皇家园林之一","中国古典园林艺术的杰作","以昆明湖、万寿山为基址，以杭州西湖为蓝本","世界文化遗产"]', '["乾隆","慈禧"]', 'https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["forbidden-city","yueyang-tower","huangshan"]', 5, 1),
('yueyang-tower', '岳阳楼', '湖南省岳阳市', 'building', '东汉-清', '东汉末年-清', '中国古代著名楼阁，江南三大名楼之一。', '岳阳楼，位于湖南省岳阳市岳阳楼区洞庭北路，是中国古代著名楼阁，江南三大名楼之一。岳阳楼始建于东汉末年，三国时期吴国鲁肃在此建阅兵楼，唐代始称岳阳楼。', '岳阳楼始建于公元220年前后，其前身相传为三国时期东吴大将鲁肃的"阅军楼"，西晋南北朝时称"巴陵城楼"，中唐李白赋诗之后，始称"岳阳楼"。', '岳阳楼因北宋范仲淹的《岳阳楼记》而闻名天下，文中"先天下之忧而忧，后天下之乐而乐"的名句成为中华民族的精神财富。它体现了中国古代文人的精神追求。', '["江南三大名楼之一","因范仲淹的《岳阳楼记》而闻名天下","中国古代建筑艺术的杰作","体现了中国古代文人的精神追求"]', '["范仲淹","滕子京","李白"]', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1586023492125-27b2c045efd7?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["summer-palace","jade-buddha-temple","huangshan"]', 6, 1),
('dujiangyan', '都江堰', '四川省成都市都江堰市', 'site', '战国', '公元前256年-公元前251年', '中国古代水利工程，世界文化遗产。', '都江堰，位于四川省成都市都江堰市城西，是中国古代伟大的水利工程，也是世界上现存最古老、至今仍在使用的水利工程之一。都江堰始建于战国时期秦昭王末年（约公元前256年-前251年），由秦国蜀郡太守李冰父子主持修建。', '都江堰位于四川省成都市都江堰市城西，坐落在成都平原西部的岷江上，始建于秦昭王末年（约公元前256年-前251年），是蜀郡太守李冰父子在前人鳖灵开凿的基础上组织修建的大型水利工程。', '都江堰的修建，解决了岷江水患，灌溉了成都平原，使成都平原成为"天府之国"。它体现了中国古代劳动人民的智慧和勇气。', '["世界上现存最古老、至今仍在使用的水利工程之一","解决了岷江水患，灌溉了成都平原","体现了中国古代劳动人民的智慧和勇气","世界文化遗产"]', '["李冰","二郎"]', 'https://images.unsplash.com/photo-1584539610135-2a2f2286f064?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1584539610135-2a2f2286f064?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1584539610135-2a2f2286f064?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1544005313-94ddf0286df2?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["great-wall","terracotta-army","huangshan"]', 7, 1),
('huangshan', '黄山', '安徽省黄山市', 'site', '自古以来', '自古以来', '中国著名风景名胜区，世界文化与自然双重遗产。', '黄山，位于安徽省南部黄山市境内，有72峰，主峰莲花峰海拔1864米，与光明顶、天都峰并称三大黄山主峰，为36大峰之一。黄山是安徽旅游的标志，是中国十大风景名胜中唯一的山岳风光。', '黄山原名"黟山"，因峰岩青黑，遥望苍黛而名。后因传说轩辕黄帝曾在此炼丹，故改名为"黄山"。黄山代表景观有"五绝三瀑"，五绝：奇松、怪石、云海、温泉、冬雪；三瀑：人字瀑、百丈泉、九龙瀑。', '黄山以奇松、怪石、云海、温泉、冬雪"五绝"闻名于世，被誉为"天下第一奇山"。它是中国山水画的重要题材，体现了中国人对自然美的独特理解。', '["世界文化与自然双重遗产","以奇松、怪石、云海、温泉、冬雪\\"五绝\\"闻名","被誉为\\"天下第一奇山\\"","中国山水画的重要题材"]', '["徐霞客","石涛"]', 'https://images.unsplash.com/photo-1528127269322-539801943592?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1528127269322-539801943592?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1528127269322-539801943592?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["summer-palace","yueyang-tower","dujiangyan"]', 8, 1),
('jade-buddha-temple', '少林寺', '河南省登封市', 'building', '北魏-今', '495年', '中国佛教禅宗祖庭，少林武术发源地。', '少林寺，位于河南省郑州市登封市嵩山五乳峰下，因坐落于嵩山腹地少室山的茂密丛林之中，故名"少林寺"。少林寺是中国佛教禅宗祖庭和中国功夫的发源地，现为世界文化遗产。', '少林寺始建于北魏太和十九年（495年），是孝文帝为了安置他所敬仰的印度高僧跋陀尊者，在与都城洛阳相望的嵩山少室山北麓敕建而成。', '少林寺是中国佛教禅宗祖庭，也是少林武术的发源地。它体现了中国佛教文化和武术文化的融合，是中国传统文化的重要代表。', '["中国佛教禅宗祖庭","少林武术发源地","世界文化遗产","体现了佛教文化与武术文化的融合"]', '["达摩","跋陀","十三棍僧"]', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80', '["https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1545569341-9eb8b30979d9?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1528164344705-47542687000d?ixlib=rb-4.0.3&auto=format&fit=crop&w=800&q=80"]', '["mogao-grottoes","potala-palace","great-wall"]', 9, 1);
